USE censo_monitoreo;

-- 1) departamentos
CREATE TABLE IF NOT EXISTS departamentos (id INT AUTO_INCREMENT PRIMARY KEY, codigo VARCHAR(10) NOT NULL, nombre VARCHAR(100) NOT NULL);

-- 2) municipios
CREATE TABLE IF NOT EXISTS municipios (id INT AUTO_INCREMENT PRIMARY KEY, id_departamento INT NOT NULL, codigo VARCHAR(10) NOT NULL, nombre VARCHAR(100) NOT NULL, CONSTRAINT fk_muni_depto FOREIGN KEY (id_departamento) REFERENCES departamentos(id));

